CONVERSATION_MESSAGES_CLASS = {
  /** The user message's bubble element. */
  userBubble: 'dial-cm-user-bubble',
  /** The assistant message's streamed content region. */
  assistantContent: 'dial-cm-assistant-content',
} as const

MessageBubble: FC<MessageBubbleProps> = ({
  role,
  beforeContent,
  onAttachmentClick,
  markdownComponents,
  markdownUrlTransform,
  ...props
}) => {
  if (role === MessageRole.Status) {
    return (
      <StatusMessageBubble
        labels={{
          titleText: props.labels?.statusTitleText,
          bodyText: props.labels?.statusBodyText ?? '',
        }}
      />
    );
  }

  if (role === MessageRole.User) {
    return (
      <UserMessageBubble
        {...props}
        beforeContent={beforeContent}
        onAttachmentClick={onAttachmentClick}
      />
    );
  }

  return (
    <AssistantMessageBubble
      {...props}
      beforeContent={beforeContent}
      markdownComponents={markdownComponents}
      markdownUrlTransform={markdownUrlTransform}
      onAttachmentClick={onAttachmentClick}
    />
  );
}

UserMessageBubble: FC<UserMessageBubbleProps> = ({
  text,
  position = BubblePosition.Bottom,
  styles: bubbleStyles,
  actions,
  hasAlwaysVisibleActions,
  attachments,
  collapsedLineCount = DEFAULT_COLLAPSED_LINE_COUNT,
  labels,
  beforeContent,
  onAttachmentClick,
  onDownloadAll,
  onAttachmentRetry,
  selectedAttachmentId,
}) => {
  const { colors, typography, className, bubbleClassName } = bubbleStyles ?? {};
  const {
    showMoreLabel = 'Show more',
    showLessLabel = 'Show less',
    showMoreAriaLabel,
    showLessAriaLabel,
    attachmentClickLabel,
    attachmentRetryLabel,
    attachmentOpenInNewTabLabel,
    userMessageAriaLabel = 'User message',
  } = labels ?? {};

  const {
    textRef,
    isTextCollapsed,
    isOverflowing,
    collapsedMaxHeight,
    expandedMaxHeight,
    isCollapsed,
    toggleCollapsed,
  } = useCollapsedText<HTMLParagraphElement>({
    text: text ?? '',
    collapsedLineCount,
  });

  const cssVars = buildCssVars({
    '--cm-bubble-user-bg': colors?.userBackground,
    '--cm-bubble-user-border': colors?.userBorder,
    '--cm-bubble-fade-start': colors?.fadeStart,
    '--cm-bubble-text': colors?.text,
    '--cm-bubble-collapsed-height': isOverflowing
      ? `${collapsedMaxHeight}px`
      : undefined,
    '--cm-bubble-expanded-height': isOverflowing
      ? `${expandedMaxHeight}px`
      : undefined,
  });

  const positionRadius =
    position === BubblePosition.Top
      ? 'rounded-ee-md rounded-se-2xl'
      : 'rounded-se-md rounded-ee-2xl';

  const textClass = mergeClasses(styles.text, typography?.fontClassName);
  const expandAriaLabel = showMoreAriaLabel ?? showMoreLabel;
  const collapseAriaLabel = showLessAriaLabel ?? showLessLabel;
  const toggleLabel = isCollapsed ? showMoreLabel : showLessLabel;
  const toggleAriaLabel = isCollapsed ? expandAriaLabel : collapseAriaLabel;
  const ToggleIcon = isCollapsed ? IconChevronDown : IconChevronUp;
  const collapsibleTextId = useId();
  return (
    <div
      role="group"
      aria-label={userMessageAriaLabel}
      style={cssVars}
      className={mergeClasses('flex w-full', className)}
    >
      <div className="ms-auto flex w-fit min-w-0 max-w-full flex-col items-end gap-4">
        <AttachmentGroup
          attachments={attachments ?? []}
          onAttachmentClick={(id) =>
            onAttachmentClick?.(
              attachments?.find((a) => a.id === id) as DisplayAttachment,
            )
          }
          onDownloadAll={onDownloadAll}
          onRetry={onAttachmentRetry}
          labels={{
            clickLabel: attachmentClickLabel,
            retryLabel: attachmentRetryLabel,
            openInNewTabLabel: attachmentOpenInNewTabLabel,
          }}
          styles={{ className: 'max-w-[640px]' }}
          selectedAttachmentId={selectedAttachmentId}
        />
        {(text || beforeContent != null) && (
          <div
            className={mergeClasses(
              styles.userBubble,
              'flex w-fit items-center justify-end rounded-es-2xl rounded-ss-2xl border px-6 py-4',
              positionRadius,
              bubbleClassName,
              CONVERSATION_MESSAGES_CLASS.userBubble,
            )}
          >
            <div className="flex min-w-0 flex-col items-start">
              {text && (
                <div
                  id={collapsibleTextId}
                  className={mergeClasses(
                    'relative overflow-hidden',
                    isOverflowing && styles.collapsibleText,
                    isOverflowing && !isCollapsed && styles.expandedText,
                    isTextCollapsed && styles.collapsedText,
                  )}
                >
                  <p
                    ref={textRef}
                    className={mergeClasses(
                      textClass,
                      'whitespace-pre-wrap text-start [overflow-wrap:anywhere]',
                    )}
                  >
                    {/*
                     * The slot renders inline at the start of the text so the
                     * text word-flows after it on the same line — the
                     * conversation input's inline-start slot behaviour.
                     * Inline placement keeps the bubble's content-sized width
                     * and the collapse line measurement honest, which an
                     * overlaid or floated slot would not; the wrapper supplies
                     * the chip-to-text gap because generic slot content
                     * carries no padding of its own. In flow when there is no
                     * text: the bubble then renders for the slot alone and
                     * needs its height.
                     */}
                    {beforeContent != null && (
                      <span className="me-1">{beforeContent}</span>
                    )}
                    {text}
                  </p>
                </div>
              )}
              {beforeContent != null && !text && <div>{beforeContent}</div>}
              {isOverflowing && (
                <LinkButton
                  label={<>{toggleLabel}</>}
                  iconBefore={
                    <ToggleIcon size={DIAL_ICON_SIZE.SM} aria-hidden="true" />
                  }
                  aria-label={toggleAriaLabel}
                  aria-expanded={!isCollapsed}
                  aria-controls={collapsibleTextId}
                  className="mt-3"
                  onClick={toggleCollapsed}
                  size={ElementSize.Small}
                />
              )}
            </div>
          </div>
        )}
        <MessageActions
          {...actions}
          isAlwaysVisible={hasAlwaysVisibleActions}
          role={MessageRole.User}
        />
      </div>
    </div>
  );
}

AssistantMessageBubble: FC<AssistantMessageBubbleProps> = ({
  text,
  styles: bubbleStyles,
  actions,
  hasAlwaysVisibleActions,
  isStreaming,
  attachments,
  beforeContent,
  afterContent,
  starters,
  onSelectStarter,
  deploymentIconUrl,
  deploymentDisplayName,
  markdownComponents,
  markdownClassNames,
  markdownUrlTransform,
  onAttachmentClick,
  onDownloadAll,
  onAttachmentRetry,
  codeBlockTheme,
  tableOnOpenInCanvas,
  labels,
  selectedAttachmentId,
}) => {
  const { colors, typography, className, bubbleClassName } = bubbleStyles ?? {};
  const {
    attachmentClickLabel,
    attachmentRetryLabel,
    attachmentOpenInNewTabLabel,
    startersAriaLabel = 'Quick reply buttons',
    thinkingLabel,
    codeBlockCopyLabel,
    codeBlockCopiedLabel,
    tableCopyLabel,
    tableCopiedLabel,
    tableDownloadCsvLabel,
    tableOpenInCanvasLabel,
    tableDownloadFilename,
    tableScrollRegionAriaLabel,
    assistantMessageAriaLabel = 'Assistant message',
    deploymentIconFallbackLabel = 'AI',
  } = labels ?? {};
  const tableActionLabels = useMemo(
    () => ({
      copyLabel: tableCopyLabel,
      copiedLabel: tableCopiedLabel,
      downloadCsvLabel: tableDownloadCsvLabel,
      openInCanvasLabel: tableOpenInCanvasLabel,
    }),
    [
      tableCopyLabel,
      tableCopiedLabel,
      tableDownloadCsvLabel,
      tableOpenInCanvasLabel,
    ],
  );
  const visibleAttachments = isStreaming
    ? (attachments ?? []).filter((a) => a.type !== AttachmentType.Audio)
    : (attachments ?? []);
  const { slotRef, firstLineIndent } = useInlineStartIndent(
    beforeContent != null && !!text,
  );
  const cssVars = buildCssVars({
    '--cm-bubble-text': colors?.text,
    '--cm-starters-divider': colors?.startersDivider,
    '--cm-bubble-first-line-indent': firstLineIndent,
  });

  const textClass = mergeClasses(styles.text, typography?.fontClassName);

  const hasDeploymentIcon = !!(deploymentIconUrl || deploymentDisplayName);

  return (
    <div
      role="group"
      aria-label={assistantMessageAriaLabel}
      style={cssVars}
      className={mergeClasses('flex w-full items-start gap-3', className)}
    >
      {hasDeploymentIcon && (
        <DeploymentIcon
          src={deploymentIconUrl}
          size={28}
          initialsName={deploymentDisplayName || deploymentIconFallbackLabel}
          labels={{
            tooltip: deploymentDisplayName ?? deploymentIconFallbackLabel,
          }}
        />
      )}
      <div className="flex w-full min-w-0 max-w-full flex-col items-start gap-5">
        <div
          className={mergeClasses(
            'flex w-full min-w-0 max-w-full flex-col items-start gap-4',
            bubbleClassName,
          )}
        >
          {/*
           * The slot overlays the text's first line from inside the text
           * container — absolutely positioned at the inline-start edge, the
           * first markdown block's first line indented past it via
           * `--cm-bubble-first-line-indent` (the measured slot width plus a
           * gap) — so the text word-flows after it, the conversation input's
           * inline-start slot behaviour. Markdown's first block cannot host
           * the slot inline (it is react-markdown output), and this bubble is
           * full-width, so the out-of-flow overlay costs nothing here. In
           * flow whenever there is no text: on its own line when the message
           * is empty, or above the streaming placeholder while the first
           * token has not arrived yet.
           */}
          {beforeContent != null && !text && (
            <div className="min-w-0">{beforeContent}</div>
          )}
          {(text || isStreaming) && (
            <div
              aria-live="polite"
              aria-atomic="false"
              className={mergeClasses(
                textClass,
                'relative min-w-0 max-w-full text-start',
                /*
                 * `text-indent` inherits, so the indent targets the markdown
                 * container's first block child (a leading list indents its
                 * every item's first line — accepted edge) rather than the
                 * text container, where it would reach every block. The
                 * `cm-bubble-markdown` wrapper class scopes the selector to
                 * the markdown container alone: the slot's overlay div is
                 * also a direct child of the text container, and
                 * host-supplied slot content of any element type must never
                 * receive the indent.
                 */
                beforeContent != null && text && FIRST_LINE_INDENT_CLASS_NAME,
                CONVERSATION_MESSAGES_CLASS.assistantContent,
              )}
            >
              {beforeContent != null && text && (
                <div ref={slotRef} className="absolute start-0 top-0">
                  {beforeContent}
                </div>
              )}
              {/*
               * The plain marker class (not a CSS-module hash) keeps the
               * indent selector above a static string Tailwind can generate.
               */}
              <div className="cm-bubble-markdown min-w-0 max-w-full">
                <MDMessageViewer
                  content={text ?? ''}
                  isStreaming={isStreaming}
                  thinkingLabel={thinkingLabel}
                  components={markdownComponents}
                  classNames={markdownClassNames}
                  urlTransform={markdownUrlTransform}
                  codeBlockCopyLabel={codeBlockCopyLabel}
                  codeBlockCopiedLabel={codeBlockCopiedLabel}
                  codeBlockTheme={codeBlockTheme}
                  tableActionLabels={tableActionLabels}
                  tableDownloadFilename={tableDownloadFilename}
                  tableOnOpenInCanvas={tableOnOpenInCanvas}
                  tableScrollRegionAriaLabel={tableScrollRegionAriaLabel}
                />
              </div>
            </div>
          )}
          <AttachmentGroup
            attachments={visibleAttachments}
            onAttachmentClick={(id) =>
              onAttachmentClick?.(
                attachments?.find((a) => a.id === id) as DisplayAttachment,
              )
            }
            onDownloadAll={onDownloadAll}
            onRetry={onAttachmentRetry}
            labels={{
              clickLabel: attachmentClickLabel,
              retryLabel: attachmentRetryLabel,
              openInNewTabLabel: attachmentOpenInNewTabLabel,
            }}
            selectedAttachmentId={selectedAttachmentId}
          />
          {afterContent}
          <MessageActions
            {...actions}
            isAlwaysVisible={hasAlwaysVisibleActions}
            role={MessageRole.Assistant}
          />
        </div>
        {starters && starters.length > 0 && onSelectStarter && (
          <div
            role="list"
            aria-label={startersAriaLabel}
            className={mergeClasses(
              'flex w-full flex-wrap gap-2 border-t pt-5',
              styles.startersDivider,
            )}
          >
            {starters.map((starter, index) => (
              <div key={index} role="listitem" className="min-w-[40px]">
                <NeutralButton
                  label={starter.title}
                  className="min-w-[40px]"
                  onClick={() => onSelectStarter(starter)}
                />
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

StatusMessageBubble: FC<StatusMessageBubbleProps> = ({
  labels: { titleText = 'Model switched.', bodyText },
}) => {
  return (
    <div role="status" aria-live="polite">
      <InfoMessageNotification
        title={titleText}
        message={bodyText}
        textClassName="flex-row flex-wrap gap-1"
      />
    </div>
  );
}

MessageActions: FC<MessageActionsProps> = ({
  role = MessageRole.User,
  onEdit,
  onEditHover,
  onDelete,
  onRegenerate,
  onCopy,
  onCopyMarkdown,
  onLike,
  onDislike,
  activeRating,
  isAlwaysVisible,
  isDisabled = false,
  className,
  labels,
  colors,
}) => {
  const { tooltips, ariaLabels } = labels ?? {};
  const [copied, setCopied] = useState<'copy' | 'markdown' | null>(null);
  const [copyStatus, setCopyStatus] = useState('');

  const hasAnyAction =
    onEdit != null ||
    onDelete != null ||
    onRegenerate != null ||
    onCopy != null ||
    onCopyMarkdown != null ||
    onLike != null ||
    onDislike != null;

  const cssVars = buildCssVars({
    '--ma-active-rating-text': colors?.activeRatingText,
  });

  const handleCopy = useCallback(() => {
    onCopy?.();
    setCopied('copy');
    setCopyStatus(ariaLabels?.copiedStatus ?? 'Copied to clipboard');
    setTimeout(() => setCopied(null), COPIED_RESET_MS);
  }, [onCopy, ariaLabels?.copiedStatus]);

  const handleCopyMarkdown = useCallback(() => {
    onCopyMarkdown?.();
    setCopied('markdown');
    setCopyStatus(
      ariaLabels?.copiedMarkdownStatus ?? 'Copied as Markdown to clipboard',
    );
    setTimeout(() => setCopied(null), COPIED_RESET_MS);
  }, [onCopyMarkdown, ariaLabels?.copiedMarkdownStatus]);

  /*
   * No handler means a read-only message: an empty toolbar with a live region
   * nothing ever populates is dead DOM, so render nothing at all.
   */
  if (!hasAnyAction) {
    return null;
  }

  return (
    <div
      role="toolbar"
