            </div>
          )}
          <AttachmentGroup
            attachments={visibleAttachments}
            onAttachmentClick={(id) =>
              onAttachmentClick?.(
                attachments?.find((a) => a.id === id) as DisplayAttachment,
              )
            }
            onDownloadAll={onDownloadAll}
            onRetry={onAttachmentRetry}
            labels={{
              clickLabel: attachmentClickLabel,
              retryLabel: attachmentRetryLabel,
              openInNewTabLabel: attachmentOpenInNewTabLabel,
            }}
            selectedAttachmentId={selectedAttachmentId}
          />
          {afterContent}
          <MessageActions
            {...actions}
            isAlwaysVisible={hasAlwaysVisibleActions}
            role={MessageRole.Assistant}
          />
        </div>
        {starters && starters.length > 0 && onSelectStarter && (
          <div
            role="list"
            aria-label={startersAriaLabel}
            className={mergeClasses(
              'flex w-full flex-wrap gap-2 border-t pt-5',
              styles.startersDivider,
            )}
          >
            {starters.map((starter, index) => (
              <div key={index} role="listitem" className="min-w-[40px]">
                <NeutralButton
                  label={starter.title}
                  className="min-w-[40px]"
                  onClick={() => onSelectStarter(starter)}
                />
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

StatusMessageBubble: FC<StatusMessageBubbleProps> = ({
  labels: { titleText = 'Model switched.', bodyText },
}) => {
  return (
    <div role="status" aria-live="polite">
      <InfoMessageNotification
        title={titleText}
        message={bodyText}
        textClassName="flex-row flex-wrap gap-1"
      />
    </div>
  );
}

MessageActions: FC<MessageActionsProps> = ({
  role = MessageRole.User,
  onEdit,
  onEditHover,
  onDelete,
  onRegenerate,
  onCopy,
  onCopyMarkdown,
  onLike,
  onDislike,
  activeRating,
  isAlwaysVisible,
  isDisabled = false,
  className,
  labels,
  colors,
}) => {
  const { tooltips, ariaLabels } = labels ?? {};
  const [copied, setCopied] = useState<'copy' | 'markdown' | null>(null);
  const [copyStatus, setCopyStatus] = useState('');

  const hasAnyAction =
    onEdit != null ||
    onDelete != null ||
    onRegenerate != null ||
    onCopy != null ||
    onCopyMarkdown != null ||
    onLike != null ||
    onDislike != null;

  const cssVars = buildCssVars({
    '--ma-active-rating-text': colors?.activeRatingText,
  });

  const handleCopy = useCallback(() => {
    onCopy?.();
    setCopied('copy');
    setCopyStatus(ariaLabels?.copiedStatus ?? 'Copied to clipboard');
    setTimeout(() => setCopied(null), COPIED_RESET_MS);
  }, [onCopy, ariaLabels?.copiedStatus]);

  const handleCopyMarkdown = useCallback(() => {
    onCopyMarkdown?.();
    setCopied('markdown');
    setCopyStatus(
      ariaLabels?.copiedMarkdownStatus ?? 'Copied as Markdown to clipboard',
    );
    setTimeout(() => setCopied(null), COPIED_RESET_MS);
  }, [onCopyMarkdown, ariaLabels?.copiedMarkdownStatus]);

  /*
   * No handler means a read-only message: an empty toolbar with a live region
   * nothing ever populates is dead DOM, so render nothing at all.
   */
  if (!hasAnyAction) {
    return null;
  }

  return (
    <div
      role="toolbar"
      aria-label={ariaLabels?.actionsGroup ?? 'Message actions'}
      style={cssVars}
      className={mergeClasses(
        'flex gap-1',
        !isAlwaysVisible && 'opacity-0 group-hover:opacity-100',
        className,
      )}
    >
      <span role="status" aria-live="polite" className="sr-only">
        {copyStatus}
      </span>
      {role === MessageRole.User ? (
        <>
          {onEdit && (
            <ToggleIconButton
              icon={
                <IconPencilMinus
                  size={DIAL_ICON_SIZE.SM}
                  aria-hidden
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              size={ElementSize.Small}
              aria-label={ariaLabels?.editMessage ?? 'Edit message'}
              tooltipProps={{ tooltip: tooltips?.edit ?? 'Edit' }}
              onClick={onEdit}
              onMouseEnter={onEditHover}
              onFocus={onEditHover}
              disabled={isDisabled}
            />
          )}
          {onDelete && (
            <ToggleIconButton
              icon={
                <IconTrashX
                  size={DIAL_ICON_SIZE.SM}
                  aria-hidden
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              size={ElementSize.Small}
              aria-label={ariaLabels?.deleteMessage ?? 'Delete message'}
              tooltipProps={{ tooltip: tooltips?.delete ?? 'Delete' }}
              onClick={onDelete}
              disabled={isDisabled}
            />
          )}
        </>
      ) : (
        <>
          {onRegenerate && (
            <ToggleIconButton
              icon={
                <IconRefresh
                  size={DIAL_ICON_SIZE.SM}
                  aria-hidden
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              size={ElementSize.Small}
              aria-label={
                ariaLabels?.regenerateResponse ?? 'Regenerate response'
              }
              tooltipProps={{ tooltip: tooltips?.regenerate ?? 'Regenerate' }}
              onClick={onRegenerate}
              disabled={isDisabled}
            />
          )}
          {onCopy && (
            <CopyIconButton
              iconSize={DIAL_ICON_SIZE.SM}
              onClick={handleCopy}
              size={ElementSize.Small}
              isCopied={copied === 'copy'}
              copyLabel={tooltips?.copy ?? 'Copy'}
              copiedLabel={tooltips?.copied ?? 'Copied!'}
              ariaLabel={ariaLabels?.copyResponse ?? 'Copy response'}
              isDisabled={isDisabled}
            />
          )}
          {onCopyMarkdown && (
            <CopyIconButton
              iconSize={DIAL_ICON_SIZE.SM}
              onClick={handleCopyMarkdown}
              size={ElementSize.Small}
              isCopied={copied === 'markdown'}
              iconCopy={
                <IconMarkdown
                  size={DIAL_ICON_SIZE.SM}
                  aria-hidden
                  stroke={DIAL_KIT_ICON_STROKE}
                />
              }
              copyLabel={tooltips?.copyMarkdown ?? 'Copy as Markdown'}
              copiedLabel={tooltips?.copiedMarkdown ?? 'Copied!'}
              ariaLabel={ariaLabels?.copyAsMarkdown ?? 'Copy as markdown'}
              isDisabled={isDisabled}
            />
          )}

          {onLike && (
            <ToggleIconButton
              icon={
                activeRating === MessageRating.Like ? (
                  <IconThumbUpFilled
                    className={styles.activeRating}
                    size={DIAL_ICON_SIZE.SM}
                    aria-hidden
                  />
                ) : (
                  <IconThumbUp
                    size={DIAL_ICON_SIZE.SM}
                    aria-hidden
                    stroke={DIAL_KIT_ICON_STROKE}
                  />
                )
              }
              size={ElementSize.Small}
              aria-label={ariaLabels?.likeResponse ?? 'Like response'}
              aria-pressed={activeRating === MessageRating.Like}
              tooltipProps={{ tooltip: tooltips?.like ?? 'Like' }}
              onClick={onLike}
              disabled={isDisabled}
            />
          )}
          {onDislike && (
            <ToggleIconButton
              icon={
                activeRating === MessageRating.Dislike ? (
                  <IconThumbDownFilled
                    className={styles.activeRating}
                    size={DIAL_ICON_SIZE.SM}
                    aria-hidden
                  />
                ) : (
                  <IconThumbDown
                    size={DIAL_ICON_SIZE.SM}
                    aria-hidden
                    stroke={DIAL_KIT_ICON_STROKE}
                  />
                )
              }
              size={ElementSize.Small}
              aria-label={ariaLabels?.dislikeResponse ?? 'Dislike response'}
              aria-pressed={activeRating === MessageRating.Dislike}
              tooltipProps={{ tooltip: tooltips?.dislike ?? 'Dislike' }}
              onClick={onDislike}
              disabled={isDisabled}
            />
          )}
        </>
      )}
    </div>
  );
}

